={{ JSON.stringify((function(){
  const parse    = $('Parse: Input').first().json || {};
  const rule     = $('DB: Insert Rule').first().json || {};
  const valid    = $('Code: Validate').first().json || {};
  const filtered = $('Code: Filter Dates').first().json || {};
  const timing   = parse.payment_timing || 'in_full';
  const seriesTotal = parseFloat(parse.rate_per_session || 0) * parseInt(filtered.dates_count || 0);
  let cycle1 = null;
  try { cycle1 = $('Code: Pick Cycle 1').first().json; } catch(e) { cycle1 = null; }
  const isCadenced = timing !== 'in_full' && cycle1 && !cycle1._seed_failed;
  const amount = isCadenced ? parseFloat(cycle1.cycle_amount || 0) : seriesTotal;
  const descParts = [];
  descParts.push('Recurring series — ' + (rule.series_name || 'Block'));
  if (isCadenced && timing === 'in_advance') descParts.push('(Cycle ' + (cycle1.cycle_number||1) + ' / ' + cycle1.sessions_count + ' sessions)');
  else if (isCadenced && timing === 'in_arrears') descParts.push('(Card on file — billed after each cycle)');
  else descParts.push('(' + (filtered.dates_count || 0) + ' sessions)');
  return {
    amount,
    recurring_series_id: rule.series_id,
    cycle_id:            isCadenced ? cycle1.cycle_id : '',
    payment_timing:      timing,
    customer_id:         valid.customer_id,
    description:         descParts.join(' '),
    success_url: 'https://andyjay72.github.io/VenueDesk/CommunityHub/checkout.html?session_id={CHECKOUT_SESSION_ID}',
    cancel_url:  'https://andyjay72.github.io/VenueDesk/CommunityHub/calendar.html'
  };
})()) }}

