const seedResp = $input.first().json;
const cycles   = seedResp?.data?.cycles || [];
const ids      = seedResp?.data?.schedule_ids || [];

if (cycles.length === 0 || ids.length === 0) {
  return [{ json: { _seed_failed: true, seedResp } }];
}

const cycle1 = cycles[0];
const cycle1Id = ids[0];

const parse  = $('Parse: Input').first().json || {};
const rule   = $('DB: Insert Rule').first().json || {};
const valid  = $('Code: Validate').first().json || {};

return [{
  json: {
    cycle_id:            cycle1Id,
    cycle_amount:        parseFloat(cycle1.amount || 0),
    cycle_number:        cycle1.cycleNumber || 1,
    period_start:        cycle1.periodStart,
    period_end:          cycle1.periodEnd,
    payment_timing:      parse.payment_timing || 'in_advance',
    recurring_series_id: rule.series_id,
    series_name:         rule.series_name || 'Block',
    customer_id:         valid.customer_id,
    sessions_count:      cycle1.sessions || 0,
  }
}];
